#include <iiGUI/FontDatabase.h>
#include <future>
#include <iostream>
#include <stdexcept>
using namespace ii;
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class T>T take(core::Result<T> value){if(!value){if(value.error().cause)std::rethrow_exception(value.error().cause);throw std::runtime_error(value.error().message);}return std::move(*value);}
struct Provider final:gui::FontProvider {
    std::vector<std::string> names{"System","Arial"};std::string system="System";bool bundled=true;int loads=0;mutable int queries=0;
    std::vector<std::string> families()const override{++queries;return names;}
    std::string system_family()const override{return system;}
    std::string resolve(const gui::FontFace& face)const override{for(const auto& name:names)if(gui::FontDatabase::fold_name(name)==gui::FontDatabase::fold_name(face.family))return name;return system;}
    gui::FontLoadReport load(std::span<const gui::FontResource> resources)override{++loads;gui::FontLoadReport report;for(const auto& resource:resources)report.resources.push_back({std::string(resource.file),bundled,bundled?"":"Missing"});if(bundled)names.push_back("Pretendard");return report;}
};
struct Fixture final {std::shared_ptr<Provider> provider=std::make_shared<Provider>();std::shared_ptr<gui::FontDatabase> db=std::make_shared<gui::FontDatabase>(provider,gui::FontFace{"System",400,"Regular"});};
void defaults(){Fixture f;check(f.db->families()==f.provider->names&&f.db->system_family()=="System"&&f.db->application_font()==gui::FontFace{"System",400,"Regular"},"Native provider state not projected");check(f.db->family_available("aRiAl")&&!f.db->family_available("Missing"),"Family lookup does not use case folding");}
void load(){Fixture f;auto report=take(f.db->load_bundled_fonts());check(report.resources.size()==10&&f.db->family_available("Pretendard")&&f.provider->loads==1,"Complete font loading failed");const auto revision=f.db->revision();(void)take(f.db->load_bundled_fonts());check(f.provider->loads==1&&f.db->revision()==revision,"Font loading repeated registration");}
void resources(){auto resources=gui::FontDatabase::bundled_fonts();check(resources.size()==10&&resources[0].file=="Inter-Regular.ttf"&&resources[1].file=="Pretendard-Regular.ttf"&&resources.back().file=="Pretendard-Black.ttf","Original bundle ordering changed");for(const auto& item:resources)check(!item.family.empty()&&!item.style.empty()&&item.weight>=100&&item.weight<=900,"Font face metadata missing");}
void missing(){Fixture f;f.provider->bundled=false;auto report=take(f.db->load_bundled_fonts());check(report.resources.size()==10&&!f.db->family_available("Pretendard"),"A missing asset fabricated availability");for(const auto& item:report.resources)check(!item.loaded&&!item.error.empty(),"Missing font lacked diagnostics");}
void refresh(){Fixture f;const auto before=f.db->revision();check(!take(f.db->refresh())&&f.db->revision()==before,"Unchanged catalogue notified");f.provider->names.push_back("New Font");check(take(f.db->refresh())&&f.db->family_available("new font")&&f.db->revision()==before+1,"Catalogue refresh did not publish the new family");}
void application(){Fixture f;check(take(f.db->set_application_font({"Arial",600,"SemiBold"}))&&f.db->application_font()->weight==600,"Application font not updated");check(!take(f.db->set_application_font({"Arial",600,"SemiBold"})),"Identical application font notified");}
void absent(){auto provider=std::make_shared<Provider>();gui::FontDatabase db(provider,std::nullopt);check(!db.application_font()&&!take(db.set_application_font({"Arial",400,"Regular"}))&&db.resolve_family("")=="System","Absent application was fabricated");}
void substitution(){Fixture f;(void)take(f.db->install_substitution("Missing","Arial"));check(f.db->substitutions("MISSING")==std::vector<std::string>{"Arial"}&&f.db->resolve_family("Missing")=="Arial","Substitution lookup failed");check(!take(f.db->install_substitution("missing","ARIAL")),"Duplicate folded substitution inserted");check(f.db->resolve_family("Arial")=="Arial","A valid primary family was replaced");}
void stack(){Fixture f;(void)take(f.db->install_substitution("Missing","Arial"));check(f.db->family_stack("Missing")==std::vector<std::string>{"Missing","Arial","System"},"Fallback stack priority or deduplication changed");}
void fold(){check(gui::FontDatabase::fold_name("STRAẞE")=="strasse"&&gui::FontDatabase::fold_name("ſemiBold")=="semibold","Unicode font case folding was reduced to ASCII");}
void validation(){Fixture f;const auto before=f.db->application_font();check(!f.db->set_application_font({"",400,"Regular"})&&!f.db->set_application_font({"Arial",0,"Regular"})&&!f.db->install_substitution("","Arial"),"Invalid font state accepted");check(f.db->application_font()==before,"Rejected font state committed");bool invalid=false;try{(void)gui::FontDatabase::fold_name(std::string("a\0b",3));}catch(const std::invalid_argument&){invalid=true;}check(invalid,"NUL font name accepted");}
void observation(){Fixture f;int changes=0;auto lease=f.db->observe([&]{++changes;check(f.db->application_font()->family=="Arial","Observer saw old application font");});(void)take(f.db->set_application_font({"Arial",400,"Regular"}));check(changes==1,"Font observation missing");lease.reset();(void)take(f.db->set_application_font({"System",400,"Regular"}));check(changes==1,"Retired font observer called");}
void failure(){Fixture f;auto lease=f.db->observe([&]{auto nested=f.db->set_application_font({"System",400,"Regular"});check(!nested&&nested.error().code==core::ErrorCode::busy,"Reentrant font mutation admitted");throw std::runtime_error("receiver");});auto result=f.db->set_application_font({"Arial",400,"Regular"});check(!result&&f.db->application_font()->family=="Arial","Receiver failure rolled back committed font");lease.reset();check(take(f.db->set_application_font({"System",400,"Regular"})),"Receiver failure left font database busy");}
void owner(){Fixture f;auto result=std::async(std::launch::async,[&]{return f.db->refresh();}).get();check(!result&&result.error().code==core::ErrorCode::wrong_executor,"Foreign font command accepted");}
void indexed(){Fixture f;const int before=f.provider->queries;for(int i=0;i<1000;++i)check(f.db->family_available("Arial")&&f.db->resolve_family("Arial")=="Arial","Cached font query changed");check(f.provider->queries==before,"Display lookup enumerated OS fonts repeatedly");}
void retirement(){auto db=std::make_shared<gui::FontDatabase>(std::make_shared<Provider>(),gui::FontFace{"System",400,"Regular"});int late=0;auto first=db->observe([&]{db.reset();});auto second=db->observe([&]{++late;});auto* borrowed=db.get();check(bool(borrowed->set_application_font({"Arial",400,"Regular"}))&&!db&&late==0,"Retired font database delivered a later callback");}
void native(std::string path){auto db=gui::FontDatabase::native(std::move(path));check(!db->system_family().empty()&&!db->families().empty(),"Native font metadata unavailable");const auto report=take(db->load_bundled_fonts());check(report.resources.size()==10&&db->family_available("Pretendard")&&db->family_available("Inter"),"Native bundled families not available");check(!db->resolve({"Pretendard",700,"Bold"}).empty(),"Native family resolution failed");}
}
int main(int argc,char** argv){try{const std::string test=argc>1?argv[1]:"defaults";if(test=="defaults")defaults();else if(test=="load")load();else if(test=="resources")resources();else if(test=="missing")missing();else if(test=="refresh")refresh();else if(test=="application")application();else if(test=="absent")absent();else if(test=="substitution")substitution();else if(test=="stack")stack();else if(test=="fold")fold();else if(test=="validation")validation();else if(test=="observation")observation();else if(test=="failure")failure();else if(test=="owner")owner();else if(test=="indexed")indexed();else if(test=="retirement")retirement();else if(test=="native"&&argc>2)native(argv[2]);else throw std::runtime_error("Unknown font database test");std::cout<<"Native font database "<<test<<" passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
